CREATE TABLE "ClientFavoriteListing" ("clientId" TEXT NOT NULL, "listingId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ClientFavoriteListing_pkey" PRIMARY KEY ("clientId", "listingId"), CONSTRAINT "ClientFavoriteListing_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ClientFavoriteListing_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "ServiceListing"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ClientFavoriteProvider" ("clientId" TEXT NOT NULL, "providerId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ClientFavoriteProvider_pkey" PRIMARY KEY ("clientId", "providerId"), CONSTRAINT "ClientFavoriteProvider_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ClientFavoriteProvider_providerId_fkey" FOREIGN KEY ("providerId") REFERENCES "Profile"("userId") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ClientListingView" ("clientId" TEXT NOT NULL, "listingId" TEXT NOT NULL, "viewedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ClientListingView_pkey" PRIMARY KEY ("clientId", "listingId"), CONSTRAINT "ClientListingView_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ClientListingView_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "ServiceListing"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ClientListingView_clientId_viewedAt_idx" ON "ClientListingView"("clientId", "viewedAt");
